　過酸化水素など分解ガスを出すもの｜通気孔付き容器★｜内圧上昇による破裂防止
　屋外貯蔵タンク｜通気管を設ける★｜出し入れ時の負圧・正圧防止
　液体の収納率｜内容積の98パーセント以下★｜熱膨張の余地を残す
　⚠「第4類はすべて通気孔付き容器」は誤り。通気孔は分解ガスを出すものやタンクの話

