        title: '温度管理と直射日光の回避',
        emoji: '🌡',
        body: `▼ゼロから：夏の車内に置いたスプレー缶が破裂した、という事故を聞いたことがあるでしょう。真夏の駐車中の車内は60度を超えます。危険物も同じで、温度が上がると2つのことが同時に起こります。1つは液体が膨張して容器の内圧が上がること。もう1つは蒸発が盛んになり、蒸気の濃度が上がることです。灯油は引火点が40度以上なので常温では引火しませんが、40度を超える環境に置かれれば、ガソリンと同じように引火するようになります。つまり温度管理とは、「その危険物を、引火点より低い温度に保つ」ための管理なのです。どんなに危険な物質でも、引火点より十分低ければ蒸気が足りず引火しません。

━━━━━━━━━━━━━━━━━━━━━━
🔑 温度が上がると何が変わるか
━━━━━━━━━━━━━━━━━━━━━━
・★蒸気圧が上がり、液面上の蒸気濃度が上がる。引火点とは、この濃度がちょうど燃焼下限界に達する温度のことです。
・★液体が膨張し、容器やタンクの内圧が上がる。だから空間容積を残し、通気管を設けます。
・★酸化・分解などの化学反応が速くなる。おおよそ10度上がると反応速度は2倍前後になり、自然発火の危険が高まります。
・★粘度が下がって漏れやすくなり、こぼれた液の広がりも速くなる。
逆に温度を下げれば、これらはすべて逆向きに働きます。冷やすことは、それだけで包括的な安全対策なのです。

━━━━━━━━━━━━━━━━━━━━━━
🔑 直射日光を避ける理由
━━━━━━━━━━━━━━━━━━━━━━
直射日光には、温度上昇のほかに次の作用があります。
・★紫外線による分解・劣化。容器の樹脂やパッキンがもろくなり、危険物自体も変質します。
・★局所的な過熱。金属容器の日の当たる面だけが高温になり、内部で対流が起き、通気管から蒸気が押し出されます。
・★屋外タンクの昼夜の温度差による呼吸作用。昼に膨張して蒸気を吐き、夜に収縮して空気を吸い込みます。この繰り返しでタンク内に空気が入り、蒸気と混ざって燃焼範囲の混合気ができることがあります。
このため屋外貯蔵タンクは白く塗装したり、散水設備を設けたりします。法令上も「危険物の性質に応じ、★遮光又は換気を行う」と定められ、遮光がここで効いてきます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 現場での温度管理の実際
━━━━━━━━━━━━━━━━━━━━━━
・屋内貯蔵所・屋外貯蔵所では、容器に収納して貯蔵する危険物の温度が★55度を超えないよう必要な措置を講じます。
・温度計、湿度計、圧力計その他の計器を★監視して、危険物の性質に応じた適正な温度・湿度・圧力を保ちます。
・特殊引火物のジエチルエーテルやアセトアルデヒドは沸点が低く、屋外貯蔵タンクでは温度管理が特に重要です。アセトアルデヒドの沸点は約20度で、夏場は液体でいられません。
・ボイラー、蒸気配管、排気管などの高温部からは距離を取ります。灯油の発火点は約220度で、赤熱していない配管でも着火します。

━━━━━━━━━━━━━━━━━━━━━━
🔑 加熱を伴う取扱いの注意
━━━━━━━━━━━━━━━━━━━━━━
工程の都合で危険物を加熱することがあります。塗料の粘度を下げる、洗浄力を上げる、といった目的です。このときの注意点は明確です。
・★引火点以上に加熱した危険物は、常温のガソリンと同じ危険性を持つと考える。加熱した重油や潤滑油から出た蒸気に引火した事故は少なくありません。
・★直火で加熱しない。蒸気加熱、温水加熱、電気ヒーター（防爆型）など、間接的な方法を用います。
・★局所的な過熱を避ける。ヒーターが液面から露出すると、その部分が発火点に達することがあります。液面より下に確実に沈める、空だき防止装置を付ける。
・★温度計と過昇温防止装置を必ず設ける。人の見張りだけに頼らない。
「引火点が高いから安全」ではなく「引火点より低い温度で使うから安全」なのだ、という言い換えを頭に入れておいてください。

【図解】温度管理の数値と根拠
　項目｜数値・措置｜理由｜
　容器貯蔵の温度｜55度を超えない★｜熱膨張と蒸気圧の上昇を防ぐ
　運搬容器の空間容積｜55度で漏れない量★｜同上
　遮光｜直射日光を避ける★｜温度上昇と紫外線劣化を防ぐ
　計器｜温度計等を監視★｜適正な温度・湿度・圧力の維持
　⚠灯油は常温では引火しないが、40度を超えればガソリン同様に危険

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「灯油は引火点が高いので、何度に加熱しても引火しない」→ ×★。引火点以上に加熱すれば引火します。加熱された灯油はガソリンと同等の危険性を持ちます。
・「屋内貯蔵所では容器の危険物の温度を70度以下に保つ」→ ×★。★55度を超えないようにします。
・「直射日光を避けるのは容器の見た目を保つためである」→ ×。温度上昇と紫外線劣化の防止です。
・「温度が上がっても引火点は下がる」→ ×。引火点は物質固有の値で、環境温度では変わりません。変わるのは「引火するかどうか」です。
・「蒸気圧が高いほど引火点は高い」→ ×。蒸気圧が高い（蒸発しやすい）ものほど引火点は★低くなります。

★ここだけ暗記
・温度管理の目的は★引火点より低く保つこと。
・容器貯蔵の温度は★55度を超えない。空間容積も★55度基準。
・法令の文言は★「性質に応じ、遮光又は換気」。
・★引火点は物質固有の値。温度で変わるのは危険な状態かどうか。`,
