・先端が液中に没した後は、飛散も液面のかくはんも起きにくくなるので、通常の流速まで上げてよい。
・ガソリンを貯蔵していたタンクに灯油や軽油を注入するときは、タンク内にガソリン蒸気が残り燃焼範囲に入っている可能性が高いため、★特に低速で開始する。
・移動タンク貯蔵所からの荷卸しで、注入ホースを注入口に緊結し、静置時間（帯電した電荷が緩和するまで待つ時間）を確保することも重要です。
数値は「初期は毎秒1メートル以下」と覚えます。試験ではこの1という数字が空欄になります。

━━━━━━━━━━━━━━━━━━━━━━
