・★接地抵抗を定期的に測定する。静電気除去を目的とする接地は、一般に100万オーム程度以下であれば十分に電荷を逃がせるとされますが、実務では十分に低い値を保つよう管理します。
・★配管のフランジ部にはボンディング（接続線）を渡す。ガスケットが絶縁物だと、そこで電気的に切れてしまいます。
・★接地端子の周辺は清掃し、腐食したら交換する。

━━━━━━━━━━━━━━━━━━━━━━
