ドラム缶から小容器へ移し替えるとき、ドラム缶と小容器を金属線でつなぐのがボンディングで、さらにドラム缶を地面につなぐのが接地です。実務では両方行います。電位差がなければ放電は起きない、という原理を押さえれば、どちらが必要かはすぐ判断できます。

━━━━━━━━━━━━━━━━━━━━━━
