・★ドラム缶からの小分け、詰替え。
・★かくはん、混合、ろ過、噴霧、洗浄の各作業。
・★タンクへの注入全般。
どれも「液体が動く」作業です。液体が動けば静電気が生まれる、と覚えておけば、接地が必要な場面を取りこぼしません。

【図解】接地とボンディング
　方法｜つなぐ相手｜目的｜
