・★水分や異物が混じった油をかき混ぜると、二相の界面で強く帯電します。水の混入した油のかくはんは危険度が跳ね上がります。
・★絶縁性の高い液体ほど電荷が逃げず蓄積します。ガソリン、ベンゼン、トルエンなどが該当します。
だから、かくはん機の羽根・軸・容器はすべて導体でつなぎ、接地することが基本になります。

