        title: '給油取扱所での取扱い',
        emoji: '⛽',
        body: `▼ゼロから：ガソリンスタンドは、私たちがいちばん身近に接する危険物施設です。法令上の名称は★給油取扱所といいます。ここが特殊なのは、危険物の知識がまったくない一般の人が、大量のガソリンのすぐそばまで自家用車で乗り入れてくる、という点です。工場なら教育された作業者しかいませんが、給油取扱所ではそうはいきません。だから設備の基準も取扱いの基準も、「素人がいる前提」で作られています。エンジンを止めさせる、はみ出したまま給油させない、といった一つ一つのルールは、すべてこの前提から導かれています。

━━━━━━━━━━━━━━━━━━━━━━
🔑 給油するときの基準
━━━━━━━━━━━━━━━━━━━━━━
政令の給油取扱所における取扱いの基準の柱は次のとおりです。
・★自動車等に給油するときは、固定給油設備を使用して直接給油すること。いったん容器に入れてから給油する、といったことはできません。
・★自動車等に給油するときは、自動車等の★原動機を停止させること。
・★自動車等の一部または全部が★給油空地からはみ出たままで給油しないこと。
・★給油するときは、固定給油設備から所定の距離を保つこと。
・★自動車等の洗浄を行う場合は、引火点を有する液体の洗剤を使用しないこと。
・★物品の販売等の業務は、原則として建築物の1階のみで行うこと。
どれも一つずつ理由があります。エンジン停止は排気管の高温部と電装品の火花を断つため、はみ出し禁止は道路上での給油による飛散と交通事故を防ぐためです。

━━━━━━━━━━━━━━━━━━━━━━
🔑 給油空地と設備の基準
━━━━━━━━━━━━━━━━━━━━━━
・★給油空地は、間口10メートル以上、奥行6メートル以上の、給油や自動車等の出入りに支障のない空地とします。
・★空地は漏れた危険物が浸透しないコンクリート等で舗装し、★排水溝と油分離装置を設け、危険物が空地以外へ流出しないようにします。
・★固定給油設備のホース機器の周囲に給油空地、注油空地を設けます。
・★専用タンクは地下に埋設し、計量口は★計量するとき以外は閉鎖しておきます。
・給油取扱所には、給油または灯油・軽油の詰替えのための作業場のほか、店舗・飲食店・展示場など、認められた用途の建築物しか設けられません。
・★見やすい箇所に「給油取扱所」の標識と「火気厳禁」の掲示板を設けます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 なぜエンジンを停止させるのか
━━━━━━━━━━━━━━━━━━━━━━
理由を分解すると4つあります。
・★排気管とマフラーが高温になっている。ガソリンの発火点は約300度ですが、触媒付近は数百度に達します。
・★オルタネーターや点火系から火花が出る可能性がある。
・★誤発進を防ぐ。ノズルを差したまま発進する事故が実際に起きています。
・★給油中に燃料があふれた場合、高温部にかかると即座に発火する。
「短時間だから」「エアコンを切りたくないから」という理由でエンジンをかけたままにするのは、法令違反であるだけでなく、物理的に危険です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 従業者が守る運用
━━━━━━━━━━━━━━━━━━━━━━
・★給油中は顧客の行動を監視する。喫煙、車内への戻り、携帯の使用に注意を払います。
・★灯油の詰替えは、注油空地で、専用の設備を用いて行う。
・★あふれさせない。満タン後の継ぎ足しはしない。
・★こぼれた燃料はただちに吸着材で回収する。水で流さない。
・★消火器の位置と使い方を全員が把握しておく。
・★危険物取扱者の立会いなしに、無資格者が取扱いをしてはならない。
・★定期点検、漏えい点検を確実に実施し、記録を保存する。

【図解】給油取扱所の取扱い基準
　項目｜基準｜理由｜
　給油方法｜固定給油設備で直接給油★｜容器を介する給油は不可
　自動車｜原動機を停止★｜高温部と電気火花の除去
　位置｜給油空地からはみ出さない★｜路上での飛散・事故防止
　洗浄｜引火点を有する洗剤は使用不可★｜洗浄中の引火防止
　⚠給油空地は間口10メートル以上、奥行6メートル以上

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけ・本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・「車体の一部が道路にはみ出していても、ノズルが届けば給油してよい」→ ×★。給油空地内に収めます。
・「アイドリング状態であればエンジンをかけたままでよい」→ ×★。原動機を停止させます。
・「ガソリンを容器に入れてから自動車に給油してよい」→ ×★。固定給油設備で直接給油します。
・「自動車の洗浄にはガソリンを使うと汚れがよく落ちる」→ ×★。引火点を有する液体洗剤は使用できません。
・「計量口は常に開けておくほうが確認しやすい」→ ×★。計量するとき以外は閉鎖します。

★ここだけ暗記
・★固定給油設備で直接給油、★原動機停止、★給油空地からはみ出さない。
・給油空地は★間口10メートル以上、奥行6メートル以上。
・★引火点を有する洗剤での洗車は不可。
・★専用タンクの計量口は計量時以外閉鎖。`,
