━━━━━━━━━━━━━━━━━━━━━━
・★ガソリンを入れていた携行缶やポリタンクに、洗わずに灯油を入れる。少量の残りでも十分危険です。
・★配管・ホースの誤接続。荷卸し時に地下タンクの油種を間違える。
・★給油機のノズルの取り違え。灯油の注油設備でガソリンを出してしまう。
・★共用のじょうご、ポンプ、計量器を洗わずに使い回す。
・★廃油に溶剤を混ぜたものを暖房用に使う。論外ですが、実際に起きています。
・★タンクローリーの区画（コンパートメント）間での残油混入。
どれも「容器・設備を共用した」ことが原因です。だから★油種ごとに専用の容器・器具を決めることが最大の予防策になります。

