【図解】事故の型と教訓
　場所｜典型的な事故｜教訓｜
　給油取扱所｜携行缶詰替え中の静電気着火★｜適合容器・除電・従業者が行う★
　タンクローリー｜荷卸し中のあふれと接地忘れ★｜検尺・接地・監視★
　貯蔵所・工場｜空ドラムの溶接爆発★｜蒸気除去と濃度測定★
　共通｜手順の省略と思い込み★｜教育訓練と予防規程★
　⚠事故は同じ型で繰り返される。過去事例は最良の教材

