━━━━━━━━━━━━━━━━━━━━━━
・★窒息消火は無効。二酸化炭素、ハロゲン化物、粉末は、酸素を断つ・連鎖を止めるという作用が、自分の中の酸素で燃える相手には効きません。
・★大量の水または泡による★冷却消火が原則。分解温度以下に冷やすことが唯一の道です。
・★ただし例外があります。★アジ化ナトリウムは水と反応して有毒で爆発性のあるものを生じるため注水を避け、★乾燥砂等を用います。
・★大量にある場合、消火は困難です。爆発のおそれがあるため、★退避と周囲への延焼防止を優先します。近づいて消そうとしてはいけません。
・消火後も分解熱が残るため、十分に冷却を続けます。

