第5類の指定数量は、危険性の程度に応じて第一種自己反応性物質が★10キログラム（危険等級1）、第二種自己反応性物質が★100キログラム（危険等級2）と定められています。全類の中でも最も小さい部類で、それだけ少量から規制されるということです。第4類の特殊引火物が50リットルだったことと比べても、いかに危険視されているかが分かります。
また、第5類の物質の多くは火薬類取締法の火薬類と重なる部分があり、爆発物としての側面を持ちます。試験で「少量でも爆発の危険がある」「大量に貯蔵しない」という記述が出たら、第5類だと見当をつけてかまいません。★危険なものほど指定数量が小さいという原則は、ここでも成り立っています。

